import os
from datetime import datetime, timedelta, timezone
from typing import Dict, List, Optional, Union

import boto3


class CloudWatchMetricComparator:
    def __init__(self, region_name: Optional[str] = None):
        self.cloudwatch = boto3.client(
            "cloudwatch",
            region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
        )

    @staticmethod
    def _normalize_dimensions(dimensions: Optional[Union[Dict[str, str], List[Dict[str, str]]]]) -> List[Dict[str, str]]:
        if not dimensions:
            return []
        if isinstance(dimensions, dict):
            return [{"Name": k, "Value": v} for k, v in sorted(dimensions.items())]
        return sorted(
            [{"Name": d["Name"], "Value": d["Value"]} for d in dimensions],
            key=lambda x: x["Name"],
        )

    def compare_metric_values(
        self,
        namespace: str,
        metric_name: str,
        resource_a_dimensions: Optional[Union[Dict[str, str], List[Dict[str, str]]]],
        resource_b_dimensions: Optional[Union[Dict[str, str], List[Dict[str, str]]]],
        start_time: Optional[datetime] = None,
        end_time: Optional[datetime] = None,
        period: int = 300,
        stat: str = "Average",
        unit: Optional[str] = None,
    ) -> Dict[str, object]:
        end_time = end_time or datetime.now(timezone.utc)
        start_time = start_time or (end_time - timedelta(hours=1))

        dims_a = self._normalize_dimensions(resource_a_dimensions)
        dims_b = self._normalize_dimensions(resource_b_dimensions)

        metric_a = {
            "Id": "a",
            "MetricStat": {
                "Metric": {
                    "Namespace": namespace,
                    "MetricName": metric_name,
                    "Dimensions": dims_a,
                },
                "Period": period,
                "Stat": stat,
            },
            "ReturnData": True,
        }

        metric_b = {
            "Id": "b",
            "MetricStat": {
                "Metric": {
                    "Namespace": namespace,
                    "MetricName": metric_name,
                    "Dimensions": dims_b,
                },
                "Period": period,
                "Stat": stat,
            },
            "ReturnData": True,
        }

        if unit:
            metric_a["MetricStat"]["Unit"] = unit
            metric_b["MetricStat"]["Unit"] = unit

        response = self.cloudwatch.get_metric_data(
            StartTime=start_time,
            EndTime=end_time,
            MetricDataQueries=[metric_a, metric_b],
            ScanBy="TimestampAscending",
        )

        results = {r["Id"]: r for r in response.get("MetricDataResults", [])}
        series_a = results.get("a", {})
        series_b = results.get("b", {})

        points_a = dict(zip(series_a.get("Timestamps", []), series_a.get("Values", [])))
        points_b = dict(zip(series_b.get("Timestamps", []), series_b.get("Values", [])))

        common_timestamps = sorted(set(points_a.keys()) & set(points_b.keys()))
        paired = [
            {
                "timestamp": ts.isoformat(),
                "resource_a": points_a[ts],
                "resource_b": points_b[ts],
                "difference": points_a[ts] - points_b[ts],
                "ratio": (points_a[ts] / points_b[ts]) if points_b[ts] not in (0, 0.0) else None,
            }
            for ts in common_timestamps
        ]

        values_a = [p["resource_a"] for p in paired]
        values_b = [p["resource_b"] for p in paired]

        summary = {
            "namespace": namespace,
            "metric_name": metric_name,
            "stat": stat,
            "period": period,
            "start_time": start_time.isoformat(),
            "end_time": end_time.isoformat(),
            "resource_a_dimensions": dims_a,
            "resource_b_dimensions": dims_b,
            "points_compared": len(paired),
            "resource_a_average": (sum(values_a) / len(values_a)) if values_a else None,
            "resource_b_average": (sum(values_b) / len(values_b)) if values_b else None,
            "average_difference": ((sum(values_a) - sum(values_b)) / len(paired)) if paired else None,
            "total_difference": (sum(values_a) - sum(values_b)) if paired else None,
            "series": paired,
        }

        return summary
